        static CountryCode of(String e164Digits) {
            for (CountryCode country : values()) {
                if (e164Digits.startsWith(country.digits)) {
                    return country;
                }
            }
            return null;
        }

        /** The '+'-prefixed dial code, e.g. {@code "+61"}. */
        String dialCode() {
            return "+" + digits;
        }
    }
